const fs = require('fs');
const args = process.argv.slice(2);
if (args.includes('--help')) { process.stdout.write('--cwd --model --prompt-file\n'); process.exit(0); }
if (args.includes('--version')) { process.stdout.write('fake-grok-1.0\n'); process.exit(0); }
if (process.env.FAKE_PROOF === 'linger') {
  const child = require('child_process').spawn(process.execPath,
    ['-e', 'setTimeout(() => {}, 12000)'],
    {detached: true, stdio: ['ignore', 'inherit', 'inherit']});
  child.unref();
}
const option = name => args[args.indexOf(name) + 1];
const prompt = fs.readFileSync(option('--prompt-file'), 'utf8');
const manifest = JSON.parse(prompt.match(/RUN_MANIFEST_JSON:\r?\n([^\r\n]+)/)[1]);
const proof = prompt.match(/PROJECT_READ_PROOF\|([^|\r\n]+)\|(\d+)\|</);
const lines = fs.readFileSync(require('path').join(option('--cwd'), proof[1]), 'utf8').split(/\r?\n/);
let n = Number(proof[2]);
if (process.env.FAKE_PROOF === 'wrong') n = n === 1 ? 2 : 1;
let final = 'PROJECT_READ_PROOF|' + proof[1] + '|' + n + '|' + lines[n-1].trim() + '\n';
let changed = [];
if (process.env.FAKE_PROOF === 'commit') {
  const root = option('--cwd');
  fs.appendFileSync(require('path').join(root, proof[1]), '\nA new line committed by the fixture.\n');
  const git = require('child_process').spawnSync;
  for (const command of [
    ['-C', root, 'add', '--', proof[1]],
    ['-C', root, '-c', 'user.name=Offline Test', '-c', 'user.email=offline@example.invalid',
      'commit', '-qm', 'worker commit']]) {
    const result = git('git', command);
    if (result.status !== 0) throw new Error(result.stderr.toString());
  }
  changed = [proof[1]];
}
if (process.env.FAKE_PROOF === 'two-commits' ||
    process.env.FAKE_PROOF === 'two-commits-last-only') {
  const root = option('--cwd');
  const git = require('child_process').spawnSync;
  for (const name of ['first.txt', 'second.txt']) {
    fs.writeFileSync(require('path').join(root, name), name + '\n');
    for (const command of [
      ['-C', root, 'add', '--', name],
      ['-C', root, '-c', 'user.name=Offline Test', '-c', 'user.email=offline@example.invalid',
        'commit', '-qm', name]]) {
      const result = git('git', command);
      if (result.status !== 0) throw new Error(result.stderr.toString());
    }
  }
  changed = process.env.FAKE_PROOF === 'two-commits-last-only'
    ? ['second.txt'] : ['first.txt', 'second.txt'];
}
final += 'DELEGATE_RESULT_JSON_BEGIN\n' + JSON.stringify({
  ...manifest, scope: 'Offline fixture', files_read: [proof[1]], changed_files: changed,
  tests: [], evidence: [], blockers: [], final_status: 'completed'
}) + '\nDELEGATE_RESULT_JSON_END';
process.stdout.write(JSON.stringify({text: final, modelUsage: {'fake-grok': {}}}));
